class Point {
public:
  constexpr Point(double xVal, double yVal) noexcept : x(xVal), y(yVal) {}
  constexpr double xValue() const noexcept { return x; }
  constexpr double yValue() const noexcept { return y; }
private:
  double x, y;
};

constexpr Point midpoint(const Point& p1, const Point& p2) noexcept {
  return { (p1.xValue() + p2.xValue()) / 2,
           (p1.yValue() + p2.yValue()) / 2 };
}

// p1 and p2 are constexpr, their values are known at compile time
constexpr Point p1(1.0, 2.0);
constexpr Point p2(3.0, 4.0);

// mid is initialized with the result of a constexpr function call
// and its value is computed entirely at compile time.
constexpr auto mid = midpoint(p1, p2);

// Can be used in other compile-time contexts
static_assert(mid.xValue() == 2.0, "Midpoint x should be 2.0");
